/**
 * Images used on the page. All current files are provisional illustrations
 * (src/assets/media/*.svg, generated by scripts/build-art.mjs). To use a real
 * photo: add it to src/assets/media, import it here, update the size and set
 * `illustration: false`. Scooter photos are set per model in rental.ts.
 */
import hero from '../assets/media/hero.svg';
import story from '../assets/media/story.svg';
import frigiliana from '../assets/media/frigiliana.svg';
import maro from '../assets/media/maro.svg';
import herradura from '../assets/media/herradura.svg';
import scooterCompact from '../assets/media/scooter-compact.svg';
import scooterTouring from '../assets/media/scooter-touring.svg';
import scooterMaxi from '../assets/media/scooter-maxi.svg';

export interface Media {
  src: string;
  width: number;
  height: number;
  illustration: boolean;
}

export const media = {
  hero: { src: hero, width: 1600, height: 1000, illustration: true },
  story: { src: story, width: 900, height: 1100, illustration: true },
  frigiliana: { src: frigiliana, width: 800, height: 1000, illustration: true },
  maro: { src: maro, width: 800, height: 1000, illustration: true },
  herradura: { src: herradura, width: 800, height: 1000, illustration: true },
} satisfies Record<string, Media>;

export const scooterArt = {
  compact: { src: scooterCompact, width: 480, height: 300, illustration: true },
  touring: { src: scooterTouring, width: 480, height: 300, illustration: true },
  maxi: { src: scooterMaxi, width: 480, height: 300, illustration: true },
} satisfies Record<string, Media>;
